// Build-time embedded migration bundle.
//
// **AUTO-GENERATED by `scripts/gen-embedded-migrations.ts`.**  Do not
// edit by hand — the codegen rebuilds this file from
// `meta/_journal.json` on every `bun run db:gen-embedded`. The CI
// drift check (`bun run check:embedded-drift`) fails if the
// committed file disagrees with the regenerated output.
//
// We import each migration's raw SQL as text and the journal as JSON.
// `bun build --compile` inlines the contents of every imported text /
// JSON asset into the binary, so the runtime never reads the
// filesystem and the engine + migration set ship as a single artifact.
//
// Drift safeguard: `migrate-embedded-bundle.test.ts` re-reads the
// on-disk SQL files at test time and asserts every embedded body's
// SHA-256 matches the file. CI fails loudly if a new migration is
// added but not registered here.

import { createHash } from "node:crypto";
import sql0000Baseline from "./0000_baseline.sql" with { type: "text" };
import sql0001HostedMeterWorkflowReviewReceipts from "./0001_hosted_meter_workflow_review_receipts.sql" with { type: "text" };
import sql0002DropTenantDlpRules from "./0002_drop_tenant_dlp_rules.sql" with { type: "text" };
import sql0003ReservedRoleNames from "./0003_reserved_role_names.sql" with { type: "text" };
import sql0004UserStartStepsHidden from "./0004_user_start_steps_hidden.sql" with { type: "text" };
import sql0005HostedWorkspaceModelKey from "./0005_hosted_workspace_model_key.sql" with { type: "text" };
import sql0006DropHostedBudgetReservations from "./0006_drop_hosted_budget_reservations.sql" with { type: "text" };
import sql0007Tasks from "./0007_tasks.sql" with { type: "text" };
import sql0008TaskRunProgressMarks from "./0008_task_run_progress_marks.sql" with { type: "text" };
import sql0009ScheduleBackoffOccurrences from "./0009_schedule_backoff_occurrences.sql" with { type: "text" };
import sql0010DesktopLogin from "./0010_desktop_login.sql" with { type: "text" };
import sql0011SetupAndApprovalRules from "./0011_setup_and_approval_rules.sql" with { type: "text" };
import sql0012RuleLimitsAndQuietHours from "./0012_rule_limits_and_quiet_hours.sql" with { type: "text" };
import sql0013RuleExpiryAndGentleAutoPause from "./0013_rule_expiry_and_gentle_auto_pause.sql" with { type: "text" };
import sql0014KlickdummyGaps from "./0014_klickdummy_gaps.sql" with { type: "text" };
import sql0015UiGaps from "./0015_ui_gaps.sql" with { type: "text" };
import journalMeta from "./meta/_journal.json" with { type: "json" };

interface JournalEntry {
  idx: number;
  tag: string;
  when: number;
  breakpoints?: boolean;
}

interface Journal {
  version: string;
  dialect: string;
  entries: JournalEntry[];
}

export interface EmbeddedMigration {
  idx: number;
  tag: string;
  when: number;
  hash: string;
  statements: string[];
}

const SQL_BY_TAG: Record<string, string> = {
  "0000_baseline": sql0000Baseline,
  "0001_hosted_meter_workflow_review_receipts": sql0001HostedMeterWorkflowReviewReceipts,
  "0002_drop_tenant_dlp_rules": sql0002DropTenantDlpRules,
  "0003_reserved_role_names": sql0003ReservedRoleNames,
  "0004_user_start_steps_hidden": sql0004UserStartStepsHidden,
  "0005_hosted_workspace_model_key": sql0005HostedWorkspaceModelKey,
  "0006_drop_hosted_budget_reservations": sql0006DropHostedBudgetReservations,
  "0007_tasks": sql0007Tasks,
  "0008_task_run_progress_marks": sql0008TaskRunProgressMarks,
  "0009_schedule_backoff_occurrences": sql0009ScheduleBackoffOccurrences,
  "0010_desktop_login": sql0010DesktopLogin,
  "0011_setup_and_approval_rules": sql0011SetupAndApprovalRules,
  "0012_rule_limits_and_quiet_hours": sql0012RuleLimitsAndQuietHours,
  "0013_rule_expiry_and_gentle_auto_pause": sql0013RuleExpiryAndGentleAutoPause,
  "0014_klickdummy_gaps": sql0014KlickdummyGaps,
  "0015_ui_gaps": sql0015UiGaps,
};

const journal = journalMeta as unknown as Journal;

function buildBundle(): EmbeddedMigration[] {
  return journal.entries
    .slice()
    .sort((a, b) => a.idx - b.idx)
    .map((e) => {
      const raw = SQL_BY_TAG[e.tag];
      if (raw === undefined) {
        // Caught by `migrate-embedded-bundle.test.ts` in CI long before
        // a binary ships.
        throw new Error(
          `embedded.ts is out of sync with meta/_journal.json: missing SQL for tag '${e.tag}'`,
        );
      }
      const statements = raw
        .split("--> statement-breakpoint")
        .map((s) => s.trim())
        .filter((s) => s.length > 0);
      const hash = createHash("sha256").update(raw).digest("hex");
      return { idx: e.idx, tag: e.tag, when: e.when, hash, statements };
    });
}

export const EMBEDDED_MIGRATIONS: readonly EmbeddedMigration[] = buildBundle();
export const EMBEDDED_JOURNAL: Journal = journal;
